package mz.bam.seeky.android;
import android.app.*;import android.content.*;import android.content.pm.ServiceInfo;import android.os.*;import java.util.concurrent.*;
/** User-started foreground study countdown; notification controls do not depend on an Activity. */
public final class StudyTimerService extends Service {
 static final String START="seeky.timer.START",TOGGLE="seeky.timer.TOGGLE",FINISH="seeky.timer.FINISH",DISCARD="seeky.timer.DISCARD",CHECK="seeky.timer.CHECK";static final int ID=97,DONE=98;static volatile boolean running;
 final Handler main=new Handler(Looper.getMainLooper());final ExecutorService worker=Executors.newSingleThreadExecutor();boolean foreground,dead;volatile int generation;volatile String last="";
 static void command(Context c,String action){Intent i=new Intent(c,StudyTimerService.class).setAction(action).putExtra("token",FocusSessions.prefs(c).getString("timer_token",""));try{c.startForegroundService(i);}catch(Exception e){AppDiagnostics.record(c,"timer-start",e);FocusSessions.prefs(c).edit().putString("timer_warning","Abra o Seeky para retomar o temporizador.").apply();}}
 static void begin(Context c,String goal,long subject,int minutes,String type){c.startForegroundService(new Intent(c,StudyTimerService.class).setAction(START).putExtra("goal",goal).putExtra("subject",subject).putExtra("minutes",minutes).putExtra("type",type));}
 public IBinder onBind(Intent i){return null;}
 public void onCreate(){super.onCreate();running=true;NotificationManager nm=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);nm.createNotificationChannel(new NotificationChannel("seeky_focus","Seeky Focus",NotificationManager.IMPORTANCE_LOW));nm.createNotificationChannel(new NotificationChannel("seeky_focus_end",AppLanguage.text(this,"Sessão concluída"),NotificationManager.IMPORTANCE_DEFAULT));}
 void ensureForeground(){if(foreground)return;Notification n=notification();if(Build.VERSION.SDK_INT>=34)startForeground(ID,n,ServiceInfo.FOREGROUND_SERVICE_TYPE_SPECIAL_USE);else startForeground(ID,n);foreground=true;}
 public int onStartCommand(Intent intent,int flags,int id){try{ensureForeground();}catch(Exception e){AppDiagnostics.record(this,"timer-foreground",e);FocusSessions.prefs(this).edit().putString("timer_warning","Abra o Seeky para retomar o temporizador.").apply();stopSelf();return START_NOT_STICKY;}Intent command=intent==null?new Intent().setAction(CHECK):intent;final int request=++generation;worker.execute(()->handle(command,request));return START_STICKY;}
 void handle(Intent i,int request){if(dead)return;try{String action=i.getAction(),token=i.getStringExtra("token");boolean updated=!CHECK.equals(action);long elapsed=SystemClock.elapsedRealtime(),wall=System.currentTimeMillis();if(START.equals(action))FocusSessions.start(this,i.getStringExtra("goal"),i.getLongExtra("subject",0),i.getIntExtra("minutes",25),i.getStringExtra("type"),elapsed,wall);else if(TOGGLE.equals(action))FocusSessions.toggle(this,token,elapsed,wall);else if(FINISH.equals(action)||DISCARD.equals(action)){FocusSessions.Result result=FocusSessions.finish(this,token,DISCARD.equals(action),elapsed,wall);if(result.changed&&!DISCARD.equals(action))completed(result.seconds);}
  SharedPreferences p=FocusSessions.prefs(this);if(p.getBoolean("timer_active",false)&&FocusClock.remaining(FocusSessions.seconds(p,elapsed,wall),p.getLong("timer_limit",1500))==0){FocusSessions.Result result=FocusSessions.finish(this,p.getString("timer_token",""),false,elapsed,wall);if(result.changed){completed(result.seconds);updated=true;}}if(updated)FocusEvents.publish();main.post(()->{if(request==generation)refresh();});
 }catch(Exception e){AppDiagnostics.record(this,"timer-operation",e);FocusSessions.prefs(this).edit().putString("timer_warning",e.getMessage()==null?"Temporizador indisponível.":e.getMessage()).apply();FocusEvents.publish();main.postDelayed(()->{if(request==generation)refresh();},3000);}}
 final Runnable tick=()->{if(!dead)try{int request=++generation;worker.execute(()->handle(new Intent().setAction(CHECK),request));}catch(RejectedExecutionException ignored){}};
 void refresh(){if(dead)return;main.removeCallbacks(tick);SharedPreferences p=FocusSessions.prefs(this);if(!p.getBoolean("timer_active",false)){cancelAlarm();stopForeground(STOP_FOREGROUND_REMOVE);foreground=false;stopSelf();return;}((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(ID,notification());long left=FocusClock.remaining(FocusSessions.seconds(p,SystemClock.elapsedRealtime(),System.currentTimeMillis()),p.getLong("timer_limit",1500));if(!p.getBoolean("timer_paused",false)){alarm(left,p.getString("timer_token",""));main.postDelayed(tick,Math.max(1000,Math.min(30000,left*1000)));}else cancelAlarm();}
 PendingIntent action(String action,int request){String token=FocusSessions.prefs(this).getString("timer_token","");Intent i=new Intent(this,StudyTimerService.class).setAction(action).setData(android.net.Uri.parse("seeky-focus://session/"+token)).putExtra("token",token);return PendingIntent.getForegroundService(this,request,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 Notification notification(){SharedPreferences p=FocusSessions.prefs(this);boolean paused=p.getBoolean("timer_paused",false);long left=FocusClock.remaining(FocusSessions.seconds(p,SystemClock.elapsedRealtime(),System.currentTimeMillis()),p.getLong("timer_limit",1500));PendingIntent open=PendingIntent.getActivity(this,97,new Intent(this,MainActivity.class).putExtra("open_focus",true),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);return new Notification.Builder(this,"seeky_focus").setSmallIcon(R.drawable.ic_seeky_notification).setContentTitle(AppLanguage.text(this,p.getString("timer_type","Foco"))+" · "+ReaderActivity.clock((int)(left*1000))).setContentText(p.getString("timer_goal",AppLanguage.text(this,"Sessão de foco"))).setWhen(System.currentTimeMillis()+left*1000).setUsesChronometer(!paused).setChronometerCountDown(true).setOngoing(true).setOnlyAlertOnce(true).setContentIntent(open).addAction(new Notification.Action.Builder(null,AppLanguage.text(this,paused?"Continuar":"Pausar"),action(TOGGLE,971)).build()).addAction(new Notification.Action.Builder(null,AppLanguage.text(this,"Registar tempo"),action(FINISH,972)).build()).build();}
 PendingIntent alarmIntent(String token){Intent i=new Intent(this,TimerAlarmReceiver.class).putExtra("token",token);return PendingIntent.getBroadcast(this,973,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 void alarm(long seconds,String token){try{((AlarmManager)getSystemService(ALARM_SERVICE)).setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,System.currentTimeMillis()+Math.max(1000,seconds*1000),alarmIntent(token));}catch(Exception e){AppDiagnostics.record(this,"timer-alarm",e);}}
 void cancelAlarm(){((AlarmManager)getSystemService(ALARM_SERVICE)).cancel(alarmIntent(""));}
 void completed(long seconds){SharedPreferences p=FocusSessions.prefs(this);PendingIntent open=PendingIntent.getActivity(this,98,new Intent(this,MainActivity.class).putExtra("open_focus",true),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification n=new Notification.Builder(this,"seeky_focus_end").setSmallIcon(R.drawable.ic_seeky_notification).setContentTitle(AppLanguage.text(this,"Sessão concluída")).setContentText(p.getString("timer_goal","")+" · "+seconds/60+" min").setAutoCancel(true).setContentIntent(open).build();try{((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(DONE,n);}catch(Exception e){AppDiagnostics.record(this,"timer-end-notification",e);}}
 public void onDestroy(){dead=true;generation++;running=false;main.removeCallbacksAndMessages(null);worker.shutdown();super.onDestroy();}
}
